{
  "mechanisms": [
    {
      "name": "asymmetric_rl_learning_rates",
      "title": "Asymmetric RL Learning Rates",
      "description": "The reinforcement learning module updates Q-values using different learning rates for positive and negative prediction errors.",
      "params": [
        {
          "name": "lr_pos",
          "bounds": [0, 1]
        },
        {
          "name": "lr_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "if r > Q_s[a]:\n                q[s, a] += lr_pos * (r - Q_s[a])\n            else:\n                q[s, a] += lr_neg * (r - Q_s[a])",
      "expressible_in_slots": true
    },
    {
      "name": "set_size_dependent_wm_lapse",
      "title": "Set-Size-Dependent WM Lapse",
      "description": "Working memory reliability decreases at higher set sizes, modeled as a lapse rate that scales linearly from 0 at set size 3 to a maximum at set size 6, blending the WM policy with a uniform distribution.",
      "params": [
        {
          "name": "lapse0",
          "bounds": [0, 1]
        }
      ],
      "evidence": "if nS <= 3:\n            lapse = 0.0\n        else:\n            lapse = np.clip(lapse0 * (float(nS - 3) / max(1.0, 6.0 - 3.0)), 0.0, 1.0)\n...\np_wm = (1.0 - lapse) * p_wm_core + lapse * p_uniform",
      "expressible_in_slots": true
    },
    {
      "name": "pe_based_arbitration",
      "title": "Prediction-Error-Based Arbitration",
      "description": "The mixture weight for the working memory policy is dynamically scaled down by the absolute magnitude of the reinforcement learning prediction error, favoring RL when surprise is high.",
      "params": [
        {
          "name": "wm_weight0",
          "bounds": [0, 1]
        }
      ],
      "evidence": "pe = r - Q_s[a]\n            eff_w = np.clip(wm_weight0 * (1.0 - abs(pe)), 0.0, 1.0)",
      "expressible_in_slots": true
    },
    {
      "name": "asymmetric_fixed_wm_update",
      "title": "Asymmetric Fixed-Rate WM Updating",
      "description": "Working memory updates perfectly after positive feedback but only partially decays the chosen action's weight and renormalizes after negative feedback, using fixed learning rates.",
      "params": [],
      "evidence": "if r > 0.0:\n\n                alpha_pos = 1.0\n                w[s, :] = (1.0 - alpha_pos) * w[s, :]\n                w[s, a] += alpha_pos\n            else:\n\n                alpha_neg = 0.2\n                w[s, a] = max(eps, (1.0 - alpha_neg) * w[s, a])\n\n                row_sum = np.sum(w[s, :])\n                if row_sum > 0:\n                    w[s, :] /= row_sum",
      "expressible_in_slots": true
    }
  ]
}
